head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vJobMode = "";
scwin.vIsurCd = "";
scwin.vSeq = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue("19000101");
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        await scwin.searchCode();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20503.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20503.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20503.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.vJobMode = "M";
        scwin.setPara(row);
        let wth = 780;
        let hgt = 370;
        let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);

        // frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF60012.gfm", "심사관련 이슈사항 수정" ,10, 10, 790, 470, "window" );
        const options = {
            id: "ULDSTF20504",
            title: "상장폐지 의사록 수정",
            type: "browserPopup",
            width: wth,
            height: hgt,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstproc/ULDSTF20504.gfm", options);
        await scwin.listSync();
        scwin.vJobMode = "";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20503.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_new_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_new_onclick = async function() {
    try {
        scwin.vJobMode = "I";
        let wth = 780;
        let hgt = 370;
        let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);

        // frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF60012.gfm", "심사관련 이슈사항 등록" ,10, 10, 790, 470, "window" );
        const options = {
            id: "ULDSTF20504",
            title: "상장폐지 의사록 등록",
            type: "browserPopup",
            width: wth,
            height: hgt,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstproc/ULDSTF20504.gfm", options);
        await scwin.listSync();
        scwin.vJobMode = "";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20503.btn_new_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20503.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name cmb_DelibComiteTpCd_onselchange
 * @description cmb_DelibComiteTpCd onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DelibComiteTpCd_onselchange = function() {

};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20503.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20503.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20503.icn_SCal_onclick" });
