};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20503.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20503.btn_cancel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const arrCid = [{
        cid: "DELIB_COMITE_TP_CD",
        cnm: "cmb_DelibComiteTpCd"
    }];
    let objCod;
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='DELIB_COMITE_TP_CD'";
    const sbmOptions = {
        id : "sbm_dts_Code",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Code=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "A^전체";
        for (j = 1; j <= dts_Code.getRowCount(); j++) {
            if (dts_Code.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
    cmb_DelibComiteTpCd.setSelectedIndex(0);

    //
    strCbd = "A^전체";
    strCbd = strCbd + ',Y' + "^" + '상장유지';
    strCbd = strCbd + ',D' + "^" + '상장폐지';
    cmb_ListComiteDelibRsltCd.CBData = strCbd;
    cmb_ListComiteDelibRsltCd.setSelectedIndex(0);

    //
    strCbd = "A^전체";
    strCbd = strCbd + ',N' + "^" + '미대상';
    strCbd = strCbd + ',Y' + "^" + '대상';
    cmb_OpnReservYn.CBData = strCbd;
    cmb_OpnReservYn.setSelectedIndex(0);
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setPara
 * @description set Para 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setPara = function(obj) {
    if (scwin.vJobMode === "M") {
        scwin.vIsurCd = dts_List.getCellData(obj, "ISUR_CD");
        scwin.vSeq = dts_List.getCellData(obj, "SEQ");
    } else {
        scwin.vIsurCd = "";
        scwin.vSeq = "";
    }
};

/**
 * @method
 * @name getParaIsurCd
 * @description get Para Isur Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParaIsurCd = function() {
    return scwin.vIsurCd;
};

/**
 * @method
 * @name getParaSeq
 * @description get Para Seq 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParaSeq = function() {
    return scwin.vSeq;
};
